package main
import ("fmt"; f "github.com/goxide-lang/std/formatting"; r "github.com/goxide-lang/std/runtime")
func guarded() (result int) { guard:=r.Assignment[int]{}; defer guard.Catch(&result); guard.Fail(42); return 0 }
func main(){fmt.Println(f.Int(guarded()),f.Bool(true));println!("std {}",7)}
